<?php
namespace Tests\Feature;use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use App\Models\{User,Role,ServiceCategory,Service};use Illuminate\Support\Facades\Hash;use Illuminate\Support\Str;
class ServiceTest extends TestCase{use RefreshDatabase;private function admin(){ $u=User::create(['name'=>'Admin','phone'=>'+201'.random_int(100000000,999999999),'password_hash'=>Hash::make('Password1'),'status'=>'ACTIVE']);$u->roles()->attach(Role::firstOrCreate(['name'=>'ADMIN']));return $u;}protected function setUp():void{parent::setUp();$this->artisan('migrate');Role::firstOrCreate(['name'=>'REGISTERED_USER']);ServiceCategory::create(['name'=>'Training','status'=>'ACTIVE']);}
public function test_public_active_services():void{$a=$this->admin();Service::create(['category_id'=>1,'title'=>'Training','short_description'=>'Short','description'=>'Long','status'=>'ACTIVE','created_by'=>$a->id]);$this->getJson('/api/v1/services')->assertOk()->assertJsonCount(1,'data.data');}
public function test_inactive_hidden():void{$a=$this->admin();Service::create(['category_id'=>1,'title'=>'Hidden','short_description'=>'Short','description'=>'Long','status'=>'INACTIVE','created_by'=>$a->id]);$this->getJson('/api/v1/services')->assertOk()->assertJsonCount(0,'data.data');}
public function test_admin_can_create_update_delete():void{$a=$this->admin();$r=$this->actingAs($a,'api')->postJson('/api/v1/admin/services',['category_id'=>1,'title'=>'Training','short_description'=>'Short','description'=>'Long']);$r->assertCreated();$id=$r->json('data.id');$this->actingAs($a,'api')->putJson("/api/v1/admin/services/$id",['title'=>'Updated'])->assertOk();$this->actingAs($a,'api')->deleteJson("/api/v1/admin/services/$id")->assertNoContent();}
public function test_unauthorized_cannot_manage():void{$this->postJson('/api/v1/admin/services',[])->assertUnauthorized();}
public function test_filtering_works():void{$a=$this->admin();Service::create(['category_id'=>1,'title'=>'Horse Training','short_description'=>'Short','description'=>'Long','status'=>'ACTIVE','created_by'=>$a->id]);$this->getJson('/api/v1/services?search=training&category_id=1')->assertOk()->assertJsonCount(1,'data.data');}}
